 49:   factory ExecutionProposal.fromJson(Map<String, dynamic> j) => ExecutionProposal(
 50:         proposalDigest: j['proposal_digest'] as String,
 51:         approvalDigest: j['approval_digest'] as String?,
 52:         turnId: j['turn_id'] as String?,
 53:         sessionId: j['session_id'] as String?,
 54:         kind: j['kind'] as String?,
 55:         provider: j['provider'] as String?,
 56:         model: j['model'] as String?,
 57:         capabilityId: j['capability_id'] as String?,
 58:         argumentDigest: j['argument_digest'] as String?,
 59:         effect: j['effect'] as String?,
 60:         reversible: j['reversible'] as bool?,
 61:         instruction: j['instruction'] as String?,
 62:         expectedFile: j['expected_file'] as String?,
 63:         arguments: (j['arguments'] as Map?)?.cast<String, dynamic>() ?? const {},
 64:         qualification: (j['qualification'] as Map?)?.cast<String, dynamic>(),
 65:       );
 66: 
 67:   final String proposalDigest;
 68:   final String? approvalDigest;
 69:   final String? turnId;
 70:   final String? sessionId;
 71:   final String? kind;
 72:   final String? provider;
 73:   final String? model;
 74:   final String? capabilityId;
 75:   final String? argumentDigest;
 76:   final String? effect;
 77:   final bool? reversible;
 78:   final String? instruction;
 79:   final String? expectedFile;
 80:   final Map<String, dynamic> arguments;
 81:   final Map<String, dynamic>? qualification;
 82: }
