 31: /// Real native-window resize hook for a Compact/Workspace transition.
 32: /// Defined here (not in a plugin file) so this plugin-free file can
 33: /// still declare the parameter type it threads down to [UriHome].
 34: typedef CompactWindowModeFn = Future<void> Function(bool isCompact);
 35: 
 36: /// Root widget. Decides between the first-run onboarding flow and the
 37: /// main application shell based on [AppState.preferences]. Everything
 38: /// below this point shares one [AppState] via [AppStateScope].
 39: class UriApp extends StatefulWidget {
 40:   const UriApp({
 41:     super.key,
 42:     required this.appState,
 43:     this.filePicker,
 44:     this.attachmentOpener,
 45:     this.onCompactModeChanged,
 46:   });
 47: 
 48:   final AppState appState;
 49: 
 50:   /// M16: how the user picks a file to attach. Supplied by main.dart in
 51:   /// the real app; null in tests, where the attach control is simply
 52:   /// not offered rather than shown inert.
 53:   final FilePickerFn? filePicker;
 54: 
 55:   /// How a tapped attachment gets opened for the user to verify.
 56:   /// Supplied by main.dart in the real app; null in tests, where
 57:   /// tapping one just reports that this build can't open it.
 58:   final AttachmentOpenerFn? attachmentOpener;
 59: 
 60:   /// Compact mode's real native-window resize hook (see
 61:   /// services/platform_window_controller.dart). Supplied by main.dart
 62:   /// in the real app; null in tests and on platforms without a native
 63:   /// implementation, where Compact still switches correctly as a pure
 64:   /// state/UI change, just without the OS window itself resizing.
 65:   final CompactWindowModeFn? onCompactModeChanged;
 66: 
 67:   @override
 68:   State<UriApp> createState() => _UriAppState();
 69: }
