162: class _RootGateState extends State<_RootGate> {
163:   @override
164:   Widget build(BuildContext context) {
165:     final appState = widget.appState;
166:     // Bootstrap fix (multi-client connectivity): a device that has
167:     // never had a working backend address configured can never log in
168:     // against the compiled-in default (http://localhost:8000,
169:     // meaningless on a phone) - and Settings > "URI server" (the only
170:     // place to fix that) was only reachable after logging in. This
171:     // screen breaks that lockout by coming BEFORE the login gate
172:     // below, exposing the exact same address/Test Connection controls
173:     // unauthenticated (GET /health only - no other endpoint is
174:     // reachable from here). Once a working address is confirmed,
175:     // AppState.hasConfiguredServerAddress flips true and this screen
176:     // never shows again this session.
177:     if (!appState.isAuthenticated && !appState.hasConfiguredServerAddress) {
178:       return const BootstrapScreen();
179:     }
180:     // Prototype 1 (multi-user identity): login is the outermost gate,
181:     // ahead of onboarding - which user's state onboarding and
182:     // everything after it operates on is decided here, once, rather
183:     // than by each screen guessing.
184:     if (!appState.isAuthenticated) {
185:       return LoginScreen(onLogin: appState.login, onSignup: appState.signup);
