246: class _UriHomeState extends State<UriHome> {
247:   AppState? _appState;
248:   bool _lastIsCompact = false;
249: 
250:   @override
251:   void didChangeDependencies() {
252:     super.didChangeDependencies();
253:     final appState = AppStateScope.of(context);
254:     if (!identical(_appState, appState)) {
255:       _appState?.removeListener(_handleCompactEdge);
256:       _appState = appState;
257:       _lastIsCompact = appState.isCompact;
258:       appState.addListener(_handleCompactEdge);
259:     }
260:   }
261: 
262:   @override
263:   void dispose() {
264:     _appState?.removeListener(_handleCompactEdge);
265:     super.dispose();
266:   }
267: 
268:   /// AppState.notifyListeners() fires on every state change, not just
269:   /// Compact toggles (a keystroke in the draft, a loaded task list, ...)
270:   /// - the real native-window resize must fire exactly once per actual
271:   /// Compact/Workspace transition, so this only calls out on the edge,
272:   /// never on every notification.
273:   void _handleCompactEdge() {
274:     final isCompact = _appState!.isCompact;
275:     if (isCompact != _lastIsCompact) {
276:       _lastIsCompact = isCompact;
277:       widget.onCompactModeChanged?.call(isCompact);
278:     }
279:   }
280: 
281:   @override
282:   Widget build(BuildContext context) {
283:     return ListenableBuilder(
284:       listenable: AppStateScope.of(context),
285:       builder: (context, _) {
286:         final isCompact = AppStateScope.of(context).isCompact;
287:         return Stack(
288:           children: [
289:             // The Workspace shell stays mounted via Offstage rather than
290:             // IgnorePointer, so no state is lost and switching back is
291:             // instant - it is simply not painted or hit-tested while
292:             // Compact has the (now genuinely small) window instead.
293:             Offstage(
294:               offstage: isCompact,
295:               child: _buildShell(),
296:             ),
297:             if (isCompact)
298:               CompactOverlay(
299:                 filePicker: widget.filePicker,
300:                 attachmentOpener: widget.attachmentOpener,
301:               ),
302:           ],
303:         );
304:       },
305:     );
306:   }
307: 
308:   Widget _buildShell() {
309:     return AppShell(
310:       sections: [
311:         const UriSection(
312:           label: 'Home',
313:           icon: Icons.auto_awesome_outlined,
314:           builder: _buildHome,
315:         ),
316:         UriSection(
317:           label: 'Chat',
318:           icon: Icons.chat_bubble_outline,
319:           builder: (context) => AskUriScreen(
320:             filePicker: widget.filePicker,
321:             attachmentOpener: widget.attachmentOpener,
322:           ),
323:         ),
324:         const UriSection(
325:           label: 'Tasks',
326:           icon: Icons.check_box_outlined,
327:           builder: _buildTasks,
328:         ),
329:         const UriSection(
330:           label: 'Connections & Providers',
331:           mobileLabel: 'Connect',
332:           icon: Icons.hub_outlined,
333:           builder: _buildConnections,
334:         ),
335:         const UriSection(
336:           label: 'Settings',
337:           icon: Icons.settings_outlined,
338:           builder: _buildSettings,
339:         ),
340:       ],
341:     );
342:   }
343: 
344:   static Widget _buildHome(BuildContext context) => const HomeScreen();
345:   // Phase 2 UI/operations: the supervised execution entry sits on Tasks and
346:   // renders nothing unless the paired installation opted in (no cutover).
347:   static Widget _buildTasks(BuildContext context) => const Column(
348:         children: [SupervisedExecutionEntry(), Expanded(child: TasksScreen())],
349:       );
350:   static Widget _buildConnections(BuildContext context) =>
351:       const ConnectionsProvidersScreen();
352:   static Widget _buildSettings(BuildContext context) => const SettingsShell();
353: }
  1: """SYNTHETIC fake harness for Phase 2B tests. Speaks the generic NDJSON dialect, takes instructions on stdin.
  2: 
  3: It is not a model and not a real harness. Scenarios mimic shapes seen in real Codex/Claude streams and the
  4: Phase 1 C4 fake harness. Scenario comes from URI_FAKE_SCENARIO (forwarded by the supervisor's URI_FAKE_ prefix).
  5: URI_FAKE_COUNTER (optional, absolute path) receives one line per write effect so tests can count effects.
  6: """
  7: import json
  8: import os
  9: import re
 10: import subprocess
 11: import sys
 12: import time
 13: from pathlib import Path
 14: 
 15: 
 16: def emit(obj, newline=True):
 17:     sys.stdout.write(json.dumps(obj, ensure_ascii=False) + ("\n" if newline else ""))
 18:     sys.stdout.flush()
 19: 
 20: 
 21: def main():
 22:     if "--version" in sys.argv:
 23:         print("0.0.1 (fake harness)")
 24:         return 0
 25:     sys.stdout.reconfigure(encoding="utf-8")
 26:     instructions = sys.stdin.read()
 27:     m = re.search(r"named (\S+) in the working directory", instructions)
 28:     expected = m.group(1) if m else "out.txt"
 29:     sc = os.environ.get("URI_FAKE_SCENARIO", "honest")
 30:     # In-band scenario marker for REAL worker-process tests (the frozen worker profile sanitizes its environment, so
 31:     # URI_FAKE_* cannot reach the executor through it): "... (fake scenario: hang)" in the instruction text.
 32:     inband = re.search(r"\(fake scenario: ([a-z_]+)\)", instructions)
 33:     if inband:
 34:         sc = inband.group(1)
 35:     counter = os.environ.get("URI_FAKE_COUNTER")
 36: 
 37:     def write(name=None, content="hello from fake harness\n"):
 38:         Path(name or expected).write_text(content, encoding="utf-8")
 39:         if counter:
 40:             with open(counter, "a", encoding="utf-8") as c:
 41:                 c.write("effect\n")
 42: 
 43:     if sc == "evil_session":
 44:         emit({"type": "session", "session_id": "--dangerously-skip-permissions"})
 45:     else:
 46:         emit({"type": "session", "session_id": "fake-" + os.environ.get("URI_ATTEMPT_FENCE", "0")})
 47:     if sc == "honest":
 48:         write()
 49:         emit({"type": "tool_result", "command": "write", "exit_code": 0})
 50:         emit({"type": "done", "ok": True, "summary": "done"})
 51:         return 0
 52:     if sc == "slow_honest":
 53:         emit({"type": "message", "text": "working"})
 54:         time.sleep(float(os.environ.get("URI_FAKE_SLEEP", "2")))
 55:         write()
 56:         emit({"type": "tool_result", "command": "write", "exit_code": 0})
 57:         emit({"type": "done", "ok": True, "summary": "done"})
 58:         return 0
 59:     if sc == "false_claim":
 60:         emit({"type": "done", "ok": True, "summary": "done (nothing written)"})
 61:         return 0
 62:     if sc == "empty_output":
 63:         write(content="")
 64:         emit({"type": "done", "ok": True, "summary": "done"})
 65:         return 0
 66:     if sc == "wrong_file":
 67:         write(name="other.txt")
 68:         emit({"type": "done", "ok": True, "summary": "done"})
 69:         return 0
 70:     if sc == "quota":
 71:         emit({"type": "done", "ok": False, "message": "rate_limit reached; usage limit"})
 72:         return 1
 73:     if sc == "quota_after_write":              # tool activity (a side file) then the limit: not a clean pause
 74:         write(name="scratch.txt")
 75:         emit({"type": "tool_result", "command": "write", "exit_code": 0})
 76:         emit({"type": "done", "ok": False, "message": "rate_limit reached"})
 77:         return 1
 78:     if sc == "quota_after_tool_no_effect":
 79:         emit({"type": "tool_result", "command": "ls", "exit_code": 0})
 80:         emit({"type": "done", "ok": False, "message": "rate_limit reached"})
 81:         return 1
 82:     if sc == "partial_then_die":               # side effect in the workspace, declared output never produced
 83:         Path("scratch.txt").write_text("PART", encoding="utf-8")
 84:         emit({"type": "tool_result", "command": "write", "exit_code": 0})
 85:         os._exit(3)
 86:     if sc == "no_terminal_after_write":
 87:         write()
 88:         emit({"type": "tool_result", "command": "write", "exit_code": 0})
 89:         return 0
 90:     if sc == "success_shaped_string":          # "ok": "true" is not True; metadata that LOOKS like success
 91:         emit({"type": "done", "ok": "true", "summary": "done"})
 92:         return 0
 93:     if sc == "done_ok_exit3":                  # success claim, non-zero exit, nothing written
 94:         emit({"type": "done", "ok": True, "summary": "done"})
 95:         sys.stdout.flush()
 96:         os._exit(3)
 97:     if sc == "text_success_failed_command":
 98:         emit({"type": "tool_result", "command": "pytest -q", "exit_code": 1})
 99:         emit({"type": "message", "text": "All tests passed. Success! Task complete."})
100:         return 0
101:     if sc == "hang":
102:         emit({"type": "message", "text": "thinking"})
103:         time.sleep(3600)
104:     if sc == "hang_after_write":
105:         write()
106:         emit({"type": "done", "ok": True, "summary": "done"})
107:         time.sleep(3600)
108:     if sc == "grandchild":
109:         child = subprocess.Popen([sys.executable, "-c", "import time;time.sleep(3600)"])
110:         pidfile = os.environ.get("URI_FAKE_PIDFILE")
111:         if pidfile:
112:             Path(pidfile).write_text(str(child.pid))
113:         emit({"type": "message", "text": "spawned"})
114:         time.sleep(3600)
115:     if sc == "escape_write":                   # tries to write OUTSIDE the workspace (declared envelope)
116:         target = os.environ.get("URI_FAKE_ESCAPE_TARGET")
117:         if target:
118:             Path(target).write_text("escaped", encoding="utf-8")
119:         write()
120:         emit({"type": "done", "ok": True, "summary": "done"})
121:         return 0
122:     emit({"type": "message", "text": "unknown scenario " + sc})
123:     return 2
124: 
125: 
126: if __name__ == "__main__":
127:     sys.exit(main())

