 11: /// Phase 2 UI/operations: the URI UI driving the supervised execution path.
 12: ///
 13: /// Flow: explicit executor choice -> text -> (clarification / confirmation)
 14: /// -> digest-bound approval card (task, provider, model, effect scope,
 15: /// qualification, digests) -> `execution_begin` -> lifecycle card polled from
 16: /// the worker (queued / approving / starting / running / terminal) with a real
 17: /// mid-run Cancel -> receipt. On open the screen lists every execution the
 18: /// worker knows about (reconnect): nothing shown here is UI memory, every
 19: /// state is re-read from the worker, which re-reads the ledger, the journal
 20: /// and the server. Nothing is simulated when no installation has opted in.
 21: class SupervisedExecutionScreen extends StatefulWidget {
 22:   const SupervisedExecutionScreen({
 23:     super.key,
 24:     this.runtimeOverride,
 25:     this.sessionId,
 26:     this.pollInterval = const Duration(milliseconds: 500),
 27:   });
 28: 
 29:   /// Tests inject a runtime; production resolves URI_CLIENT_MANIFEST + opt-in.
 30:   final SupervisedRuntime? runtimeOverride;
 31:   final String? sessionId;
 32:   final Duration pollInterval;
 33: 
 34:   @override
 35:   State<SupervisedExecutionScreen> createState() => _SupervisedExecutionScreenState();
 36: }
 37: 
 38: String _uuid4() {
 39:   final r = Random.secure();
 40:   final b = List<int>.generate(16, (_) => r.nextInt(256));
 41:   b[6] = (b[6] & 0x0f) | 0x40;
 42:   b[8] = (b[8] & 0x3f) | 0x80;
 43:   final h = b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();
 44:   return '${h.substring(0, 8)}-${h.substring(8, 12)}-${h.substring(12, 16)}-${h.substring(16, 20)}-${h.substring(20)}';
 45: }
 46: 
 47: String _short(String? digest) => digest == null ? 'â€”' : (digest.length > 16 ? '${digest.substring(0, 16)}â€¦' : digest);
 48: 
 49: String _when(double? epochSeconds) {
 50:   if (epochSeconds == null) return 'â€”';
 51:   final t = DateTime.fromMillisecondsSinceEpoch((epochSeconds * 1000).round());
 52:   return t.toIso8601String().replaceFirst('T', ' ').substring(0, 19);
 53: }
 54: 
 55: String _shortId(String id) => id.length > 8 ? id.substring(0, 8) : id;
 56: 
 57: class _SupervisedExecutionScreenState extends State<SupervisedExecutionScreen> {
 58:   SupervisedRuntime? _runtime;
 59:   String? _unavailable;
 60:   Map<String, dynamic> _preflight = const {};
 61:   List<HarnessStatus> _harnesses = const [];
 62:   ReasoningChoice? _choice; // never preselected: the user chooses
 63:   late final String _session = widget.sessionId ?? _uuid4();
 64:   final _text = TextEditingController();
 65:   SupervisedTurn? _pending; // approval card: proposal shown, nothing sent yet
 66:   SupervisedTurn? _question;
 67:   SupervisedTurn? _confirm;
 68:   ExecutionStatus? _execution;
 69:   List<ExecutionSummary> _history = const [];
 70:   Map<String, dynamic>? _startup;
 71:   Timer? _poll;
 72:   String? _outcome;
 73:   bool _busy = false;
 74: 
 75:   @override
 76:   void initState() {
 77:     super.initState();
 78:     _connect();
 79:   }
 80: 
 81:   Future<void> _connect() async {
 82:     try {
 83:       _runtime = widget.runtimeOverride ??
 84:           await SupervisedWorkerRuntime.fromManifest(Platform.environment['URI_CLIENT_MANIFEST']);
 85:       if (_runtime == null) {
 86:         setState(() => _unavailable = 'No paired client installation has opted in to the supervised profile '
 87:             '(control/ui-supervised-profile.json). Nothing is simulated.');
 88:         return;
 89:       }
 90:       final pre = await _runtime!.preflight();
 91:       final list = await _runtime!.discoverHarnesses();
 92:       if (!mounted) return;
 93:       setState(() {
 94:         _preflight = pre;
 95:         _harnesses = list;
 96:       });
 97:       await _reconnect();
 98:     } catch (e) {
 99:       if (mounted) setState(() => _unavailable = 'Supervised worker unavailable: $e');
100:     }
101:   }
102: 
103:   /// Reconnect: whatever the worker knows (durable records, reconciled at its
104:   /// start) is listed; an execution still active in this worker is followed.
105:   Future<void> _reconnect() async {
106:     final listing = await _runtime!.listExecutions();
107:     if (!mounted) return;
108:     setState(() {
109:       _history = listing.executions;
110:       _startup = listing.startup;
111:     });
112:     final active = listing.active;
113:     if (active != null) {
114:       await _focus(active);
115:     } else if (_execution != null) {
116:       await _focus(_execution!.id);
117:     }
118:   }
119: 
120:   Future<void> _focus(String executionId) async {
121:     try {
122:       final st = await _runtime!.executionStatus(executionId);
123:       if (!mounted) return;
124:       setState(() => _execution = st);
125:       _pollWhileActive();
126:     } catch (e) {
127:       if (mounted) setState(() => _outcome = 'Blocked: $e');
128:     }
129:   }
130: 
131:   void _pollWhileActive() {
132:     _poll?.cancel();
133:     _poll = null;
134:     final current = _execution;
135:     if (current == null || current.isTerminal) return;
136:     _poll = Timer.periodic(widget.pollInterval, (_) => _refresh());
137:   }
138: 
139:   Future<void> _refresh() async {
140:     final current = _execution;
141:     if (current == null || _runtime == null) return;
142:     try {
143:       final st = await _runtime!.executionStatus(current.id);
144:       if (!mounted) return;
145:       setState(() => _execution = st);
146:       if (st.isTerminal) {
147:         _poll?.cancel();
148:         _poll = null;
149:         final listing = await _runtime!.listExecutions();
150:         if (mounted) setState(() => _history = listing.executions);
151:       }
152:     } catch (e) {
153:       if (mounted) setState(() => _outcome = 'Status unavailable: $e');
154:       _poll?.cancel();
155:       _poll = null;
156:     }
157:   }
158: 
159:   @override
160:   void dispose() {
161:     _poll?.cancel();
162:     _text.dispose();
163:     _runtime?.close();
164:     super.dispose();
165:   }
166: 
167:   Future<void> _send() async {
168:     final choice = _choice;
169:     if (choice == null || _text.text.trim().isEmpty) return;
170:     setState(() {
171:       _busy = true;
172:       _outcome = null;
173:     });
174:     try {
175:       _apply(await _runtime!.startTurn(_session, _text.text.trim(), choice));
176:     } catch (e) {
177:       setState(() => _outcome = 'Blocked: $e');
178:     } finally {
179:       if (mounted) setState(() => _busy = false);
180:     }
181:   }
182: 
183:   void _apply(TurnResult result) {
184:     final turn = result is SupervisedTurn ? result : SupervisedTurn(state: result.state, turnId: result.turnId,
185:         code: result.code, message: result.message, approval: result.approval, clarification: result.clarification,
186:         confirmation: result.confirmation, intent: result.intent);
187:     setState(() {
188:       _question = turn.needsClarification ? turn : null;
189:       _confirm = turn.needsConfirmation ? turn : null;
190:       if (turn.needsApproval) {
191:         _pending = turn;
192:       } else {
193:         _pending = null;
194:         _outcome = (_question != null || _confirm != null) ? null : '${turn.code ?? turn.state}: ${turn.message ?? ''}';
195:       }
196:       if (_question != null) _text.clear();
197:     });
198:   }
