200:   Future<void> _intent(Map<String, dynamic> decision) async {
201:     final choice = _choice;
202:     if (choice == null) return;
203:     setState(() => _busy = true);
204:     try {
205:       _apply(await _runtime!.intentDecision(_session, choice, decision));
206:     } catch (e) {
207:       setState(() => _outcome = 'Blocked: $e');
208:     } finally {
209:       if (mounted) setState(() => _busy = false);
210:     }
211:   }
212: 
213:   /// Approve: echo exactly the two digests of the card on screen. The worker
214:   /// refuses anything else and drops the turn.
215:   Future<void> _approveAndRun() async {
216:     final pending = _pending;
217:     final proposal = pending?.proposal;
218:     if (pending == null || pending.turnId == null || proposal == null || proposal.approvalDigest == null) return;
219:     setState(() => _busy = true);
220:     try {
221:       final handle = await _runtime!.beginExecution(pending.turnId!, proposal.approvalDigest!, proposal.proposalDigest);
222:       setState(() {
223:         _pending = null;
224:         _outcome = null;
225:       });
226:       await _focus(handle.id);
227:     } catch (e) {
228:       setState(() {
229:         // A refused begin drops the turn worker-side too, except when the worker only asked us to wait
230:         // (another execution is in flight): the card stays, the approval is still the user's to give.
231:         if (!(e is PairedRuntimeException && e.code == 'EXECUTION_IN_PROGRESS')) _pending = null;
232:         _outcome = 'Blocked: $e';
233:       });
234:     } finally {
235:       if (mounted) setState(() => _busy = false);
236:     }
237:   }
238: 
239:   Future<void> _decline() async {
240:     final pending = _pending;
241:     if (pending == null || pending.turnId == null) return;
242:     setState(() => _busy = true);
243:     try {
244:       _apply(await _runtime!.decide(pending.turnId!, false));
245:     } catch (e) {
246:       setState(() {
247:         _pending = null;
248:         _outcome = 'Blocked: $e';
249:       });
250:     } finally {
251:       if (mounted) setState(() => _busy = false);
252:     }
253:   }
254: 
255:   Future<void> _cancel() async {
256:     final current = _execution;
257:     if (current == null) return;
258:     setState(() => _busy = true);
259:     try {
260:       await _runtime!.cancelExecution(current.id);
261:       await _refresh();
262:       _pollWhileActive();
263:     } catch (e) {
264:       setState(() => _outcome = 'Cancel refused: $e');
265:       await _refresh();
266:     } finally {
267:       if (mounted) setState(() => _busy = false);
268:     }
269:   }
