264: /// Boundary to the supervised worker. Everything here comes from the real
265: /// worker; the UI is never the authority for any of it.
266: abstract class SupervisedRuntime implements PairedRuntime {
267:   Future<Map<String, dynamic>> preflight();
268:   Future<ExecutionHandle> beginExecution(String turnId, String approvalDigest, String proposalDigest);
269:   Future<ExecutionStatus> executionStatus(String executionId);
270:   Future<Map<String, dynamic>> cancelExecution(String executionId);
271:   Future<ExecutionListing> listExecutions();
272: }
273: 
274: /// Real implementation over the Phase 2 worker profile.
275: class SupervisedWorkerRuntime implements SupervisedRuntime {
276:   SupervisedWorkerRuntime._(this._process);
277: 
278:   final Process _process;
279:   final _pending = <Completer<Map<String, dynamic>>>[];
280:   bool _listening = false;
281:   bool _closed = false;
282: 
283:   /// True only when a paired client installation is configured AND its client
284:   /// root carries the explicit supervised-profile opt-in file. Synchronous and
285:   /// read-only; never creates anything.
286:   static bool optInConfigured(String? manifestPath) {
287:     final manifest = _readManifest(manifestPath);
288:     if (manifest == null) return false;
289:     return _readOptIn(manifest) != null;
290:   }
291: 
292:   static Map<String, dynamic>? _readManifest(String? manifestPath) {
293:     if (manifestPath == null || manifestPath.isEmpty) return null;
294:     try {
295:       final file = File(manifestPath);
296:       if (!file.existsSync()) return null;
297:       final json = jsonDecode(file.readAsStringSync());
298:       return json is Map<String, dynamic> ? json : null;
299:     } catch (_) {
300:       return null;
301:     }
302:   }
303: 
304:   static Map<String, dynamic>? _readOptIn(Map<String, dynamic> manifest) {
305:     final root = manifest['client_root'];
306:     if (root is! String || root.isEmpty) return null;
307:     try {
308:       final file = File('$root${Platform.pathSeparator}${supervisedProfileFile.replaceAll('/', Platform.pathSeparator)}');
309:       if (!file.existsSync()) return null;
310:       final json = jsonDecode(file.readAsStringSync());
311:       if (json is! Map<String, dynamic>) return null;
312:       if (json['schema'] != supervisedProfileSchema || json['worker_profile'] != supervisedWorkerProfile) return null;
313:       return json;
314:     } catch (_) {
315:       return null;
316:     }
317:   }
318: 
319:   /// Returns null when the installation has not opted in. Spawns the Phase 2
320:   /// worker profile from the manifest's pinned `source_root` with the same
321:   /// interpreter and client root the frozen worker uses, then verifies through
322:   /// `preflight` that the worker really is the supervised profile.
323:   static Future<SupervisedWorkerRuntime?> fromManifest(String? manifestPath) async {
324:     final manifest = _readManifest(manifestPath);
325:     if (manifest == null || _readOptIn(manifest) == null) return null;
326:     final sourceRoot = manifest['source_root'] as String;
327:     final entrypoint = '$sourceRoot${Platform.pathSeparator}${supervisedWorkerEntrypoint.replaceAll('/', Platform.pathSeparator)}';
328:     return spawn(
329:       interpreter: manifest['interpreter'] as String,
330:       entrypoint: entrypoint,
331:       manifestPath: manifestPath!,
332:       workingDirectory: manifest['client_root'] as String,
333:     );
334:   }
335: 
336:   /// Spawns the worker and checks its profile. `extraArgs` exists for the live
337:   /// test harness only (fixture qualification); `fromManifest` never passes any.
338:   static Future<SupervisedWorkerRuntime> spawn({
339:     required String interpreter,
340:     required String entrypoint,
341:     required String manifestPath,
342:     required String workingDirectory,
343:     List<String> extraArgs = const [],
344:   }) async {
345:     final process = await Process.start(
346:       interpreter,
347:       ['-B', '-I', entrypoint, '--manifest', manifestPath, ...extraArgs],
348:       workingDirectory: workingDirectory,
349:     );
350:     final runtime = SupervisedWorkerRuntime._(process).._listen();
351:     try {
352:       final pre = await runtime.preflight();
353:       if (pre['worker_profile'] != supervisedWorkerProfile || pre['production_cutover'] != false) {
354:         throw PairedRuntimeException('WORKER_PROFILE_MISMATCH');
355:       }
356:       final lifecycle = pre['execution_lifecycle'];
357:       if (lifecycle is! List || !lifecycle.contains('execution_begin') || !lifecycle.contains('execution_cancel')) {
358:         throw PairedRuntimeException('EXECUTION_LIFECYCLE_UNAVAILABLE');
359:       }
360:     } catch (_) {
361:       await runtime.close();
362:       rethrow;
363:     }
364:     return runtime;
365:   }
366: 
367:   void _listen() {
368:     if (_listening) return;
369:     _listening = true;
370:     final bytes = <int>[];
371:     _process.stdout.listen((chunk) {
372:       bytes.addAll(chunk);
373:       while (bytes.length >= 4) {
374:         final size = ByteData.sublistView(Uint8List.fromList(bytes.sublist(0, 4))).getUint32(0, Endian.big);
375:         if (bytes.length < 4 + size) return;
376:         final body = utf8.decode(bytes.sublist(4, 4 + size));
377:         bytes.removeRange(0, 4 + size);
378:         if (_pending.isNotEmpty) {
379:           _pending.removeAt(0).complete(jsonDecode(body) as Map<String, dynamic>);
380:         }
381:       }
382:     }, onDone: () {
383:       for (final waiter in _pending) {
384:         waiter.completeError(PairedRuntimeException('WORKER_EXITED'));
385:       }
386:       _pending.clear();
387:     });
388:     _process.stderr.drain<void>();
389:   }
390: 
391:   Future<Map<String, dynamic>> _raw(Map<String, dynamic> command) {
392:     if (_closed) return Future.error(PairedRuntimeException('WORKER_CLOSED'));
393:     final completer = Completer<Map<String, dynamic>>();
394:     _pending.add(completer);
395:     final payload = utf8.encode(jsonEncode(command));
396:     final header = ByteData(4)..setUint32(0, payload.length, Endian.big);
397:     _process.stdin.add(header.buffer.asUint8List());
398:     _process.stdin.add(payload);
399:     return completer.future.timeout(const Duration(minutes: 5), onTimeout: () {
400:       throw PairedRuntimeException('WORKER_TIMEOUT');
401:     });
402:   }
