404:   Future<Map<String, dynamic>> _call(Map<String, dynamic> command) async {
405:     final reply = await _raw(command);
406:     if (reply['result'] != 'OK') {
407:       throw PairedRuntimeException((reply['code'] as String?) ?? 'CLIENT_COMMAND_REFUSED');
408:     }
409:     return reply['value'] as Map<String, dynamic>;
410:   }
