 38: String _uuid4() {
 39:   final r = Random.secure();
 40:   final b = List<int>.generate(16, (_) => r.nextInt(256));
 41:   b[6] = (b[6] & 0x0f) | 0x40;
 42:   b[8] = (b[8] & 0x3f) | 0x80;
 43:   final h = b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();
 44:   return '${h.substring(0, 8)}-${h.substring(8, 12)}-${h.substring(12, 16)}-${h.substring(16, 20)}-${h.substring(20)}';
 45: }
