 84:           await SupervisedWorkerRuntime.fromManifest(Platform.environment['URI_CLIENT_MANIFEST']);
 85:       if (_runtime == null) {
 86:         setState(() => _unavailable = 'No paired client installation has opted in to the supervised profile '
