100:     }
101:   }
102: 
103:   /// Reconnect: whatever the worker knows (durable records, reconciled at its
104:   /// start) is listed; an execution still active in this worker is followed.
105:   Future<void> _reconnect() async {
106:     final listing = await _runtime!.listExecutions();
107:     if (!mounted) return;
108:     setState(() {
109:       _history = listing.executions;
110:       _startup = listing.startup;
111:     });
112:     final active = listing.active;
113:     if (active != null) {
