131:   void _pollWhileActive() {
132:     _poll?.cancel();
133:     _poll = null;
134:     final current = _execution;
135:     if (current == null || current.isTerminal) return;
136:     _poll = Timer.periodic(widget.pollInterval, (_) => _refresh());
137:   }
