139:   Future<void> _refresh() async {
140:     final current = _execution;
141:     if (current == null || _runtime == null) return;
142:     try {
143:       final st = await _runtime!.executionStatus(current.id);
144:       if (!mounted) return;
145:       setState(() => _execution = st);
146:       if (st.isTerminal) {
147:         _poll?.cancel();
148:         _poll = null;
